import flatpickr from "flatpickr";
import "flatpickr/dist/flatpickr.min.css";

import iziToast from "izitoast";
import "izitoast/dist/css/iziToast.min.css";

const input = document.querySelector("#datetime-picker");
const btnStart = document.querySelector("[data-start]");
const refs = {
  days: document.querySelector("[data-days]"),
  hours: document.querySelector("[data-hours]"),
  minutes: document.querySelector("[data-minutes]"),
  seconds: document.querySelector("[data-seconds]"),
};

let userSelectedDate = null;
let timerId = null;

disable(btnStart, true);

const fp = flatpickr(input, {
  enableTime: true,
  time_24hr: true,
  defaultDate: new Date(),
  minuteIncrement: 1,
  onClose(selectedDates) {
        const picked = selectedDates[0];
      if (!picked || picked.getTime() <= Date.now()) {
      iziToast.error({
        title: "Упс!",
        message: "Please choose a date in the future",
        position: "topCenter",
      });
      userSelectedDate = null;
      disable(btnStart, true);
      return;
    }
    userSelectedDate = picked;
    disable(btnStart, false);
  },
});

btnStart.addEventListener("click", () => {
    if (!userSelectedDate) return;
    disable(btnStart, true);
    disable(input, true);
    if (timerId) clearInterval(timerId);

    tick();
    timerId = setInterval(tick, 1000);
});

function tick() {
  const diff = userSelectedDate.getTime() - Date.now();

  if (diff <= 0) {
    clearInterval(timerId);
    timerId = null;
    updateClock({ days: 0, hours: 0, minutes: 0, seconds: 0 });
        disable(input, false);  
      return;
  }

  updateClock(convertMs(diff));
}

function updateClock({ days, hours, minutes, seconds }) {
    refs.days.textContent = String(days);
    refs.hours.textContent = addLeadingZero(hours);
  refs.minutes.textContent = addLeadingZero(minutes);
  refs.seconds.textContent = addLeadingZero(seconds);
}

function addLeadingZero(value) {
  return String(value).padStart(2, "0");
}

function disable(el, isDisabled) {
  el.disabled = isDisabled;
}
function convertMs(ms) {
  // Number of milliseconds per unit of time
  const second = 1000;
  const minute = second * 60;
  const hour = minute * 60;
  const day = hour * 24;

  // Remaining days
  const days = Math.floor(ms / day);
  // Remaining hours
  const hours = Math.floor((ms % day) / hour);
  // Remaining minutes
  const minutes = Math.floor(((ms % day) % hour) / minute);
  // Remaining seconds
  const seconds = Math.floor((((ms % day) % hour) % minute) / second);

  return { days, hours, minutes, seconds };
}
